from pathlib import Path

from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.flows import map as m
from docich.hanjuku_speedrun.hanjuku.os_layer.pixels import read_png
from docich.hanjuku_speedrun.hanjuku_screen import Screen

SEA = Path(__file__).parent.parent / 'fixtures' / 'hanjuku' / 'g1190-ch9-target-marker-over-sea-565.png'
STEP = 'I:c9:サヌト>オシロガ:78'


def memory():
    cell = list(chart.castles(9)['オシロガ'])
    return {'chapter': 9, 'tick': 1000, '_records': [], 'cursor': cell,
            'captured': ['ハヤク', 'タオ', 'サヌト']}


def order():
    return {'step': STEP, 'source': 'サヌト', 'target': 'オシロガ', 'purpose': 'attack'}


def decisions(mem):
    return [r['decision'] for r in mem['_records']]


def test_a_cell_match_with_the_marker_over_the_sea_is_not_confirmed():
    mem = memory()
    screen = Screen([], None, '', kind='map_target', marker=(215, 25))
